import 'dart:convert';

import 'datum.dart';

class GetNotificationsResponse {
	List<Datum>? data;

	GetNotificationsResponse({this.data});

	factory GetNotificationsResponse.from(Map<String, dynamic> data) {
		return GetNotificationsResponse(
			data: (data['data'] as List<dynamic>?)
						?.map((e) => Datum.(e as Map<String, dynamic>))
						.toList(),
		);
	}



	Map<String, dynamic> () {
		return {
			'data': data?.map((e) => e.()).toList(),		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [GetNotificationsResponse].
	factory GetNotificationsResponse.fromJson(String data) {
		return GetNotificationsResponse.from(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [GetNotificationsResponse] to a JSON string.
	String toJson() => json.encode(());
}
